use crate::{cq11 as b,catalog,model::*,rules::*,generated::GeneratedKind,unit_support::*};
fn token(g:&mut Game,seat:usize)->String{let c=g.make_generated(GeneratedKind::Cultist,seat).unwrap();let id=c.id.clone();g.regions[0].cards.push(c);id}
fn top(g:&mut Game){for _ in 0..20{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn activate(id:&str,ids:Vec<String>)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::DESTROY.into()),region:Some(1),cost_selected:Some(ids),..Action::new("activate")}}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
fn deploy()->Game{let mut g=game();fund(&mut g,0,"JC042",2);let id=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});top(&mut g);g}
#[test]fn cq11_original_catalog_definition_and_token_non_asset(){assert_current_serial_catalog();let c=catalog::card(b::ID);assert!(!c.supported);assert_eq!((c.cost,c.color.as_str(),c.defense),(2,"红",Some(1)));let t=catalog::card(b::TOKEN);assert!(!t.supported);assert_eq!(t.cost,0);assert!(t.loyalty.is_empty());let mut g=game();let c=g.make_generated(GeneratedKind::Cultist,0).unwrap();assert!(g.current_non_asset(&c,0));}
#[test]fn cq11_optional_real_deploy_generates_one_or_declines(){for yes in [true,false]{let mut g=deploy();let p=g.pending.clone().expect("entry pending");assert_eq!(p.choice.options.len(),1);let ids=if yes{vec![p.choice.options[0].id.clone()]}else{vec![]};choose(&mut g,ids);top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition==b::TOKEN).count(),usize::from(yes));restore(&mut g);}}
#[test]fn cq11_token_three_cost_source_can_leave_physical_cards_go_grave(){let mut g=game();let t=token(&mut g,0);let a=field(&mut g,b::ID,0);let c=field(&mut g,"JC042",0);act(&mut g,0,activate(&t,vec![t.clone(),a,c]));assert!(g.board(&t).is_none());assert_eq!(g.players[0].graveyard.len(),2);assert!(!g.regions[1].destroyed);top(&mut g);assert!(g.regions[1].destroyed);assert!(!g.batch3_physical_cards().any(|c|c.definition==b::TOKEN));restore(&mut g);}
#[test]fn cq11_three_cost_rejects_duplicate_short_hidden_enemy_and_non_cultist(){let mut g=game();let t=token(&mut g,0);let a=field(&mut g,b::ID,0);let c=field(&mut g,"JC042",0);let enemy=token(&mut g,1);let ordinary=field(&mut g,"JC125",0);for ids in [vec![t.clone();3],vec![a.clone(),c.clone()],vec![t.clone(),a.clone(),enemy],vec![t.clone(),a.clone(),ordinary]]{reject(&mut g,0,activate(&t,ids));}g.board_mut(&c).unwrap().face_down=true;reject(&mut g,0,activate(&t,vec![t.clone(),a,c]));}
#[test]fn cq11_token_hidden_normal_zero_reveal_and_corrupt_stack_rejected(){let mut g=game();let t=token(&mut g,0);let birth=g.board(&t).unwrap().1.generated.clone();g.hide_in_place(&t);let hidden=g.regions[0].cards[0].id.clone();restore(&mut g);assert!(g.legal_actions(0).iter().any(|a|a.action.kind=="reveal"&&a.action.card_id.as_deref()==Some(&hidden)));act(&mut g,0,Action{card_id:Some(hidden),..Action::new("reveal")});for n in 0..4{let mut x=g.clone();let i=x.stack.last_mut().unwrap();match n{0=>i.frame=None,1=>i.frame.as_mut().unwrap().source.card.definition="JC001".into(),2=>i.card.as_mut().unwrap().generated=None,_=>i.frame.as_mut().unwrap().ability_key="deploy".into()};bad(&g,&x);}top(&mut g);assert!(!g.regions[0].cards[0].face_down);assert_eq!(g.regions[0].cards[0].generated,birth);assert!(g.players[0].assets.is_empty());restore(&mut g);}
#[test]fn cq11_generated_departure_hide_seal_and_entity_identity(){for bottom in [false,true]{let mut g=game();let id=token(&mut g,0);if bottom{g.to_bottom(&id);}else{g.return_hand(&id);}assert!(!g.batch3_physical_cards().any(|c|c.definition==b::TOKEN));restore(&mut g);}let mut g=game();let id=token(&mut g,0);let host=field(&mut g,"JC125",0);let c=g.leave_board(&id).unwrap().1;g.seal_card_on_valid_host(c,0,&host);restore(&mut g);assert_eq!(g.sealed_cards.len(),1);g.return_hand(&host);assert!(g.sealed_cards.is_empty());assert!(!g.batch3_physical_cards().any(|c|c.definition==b::TOKEN));restore(&mut g);}
#[test]fn cq11_three_cost_corrupt_receipt_and_definition_rejected(){let mut g=game();let t=token(&mut g,0);let a=token(&mut g,0);let c=token(&mut g,0);act(&mut g,0,activate(&t,vec![t.clone(),a,c]));for n in 0..4{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.steps.clear(),1=>f.already_paid.clear(),2=>if let PaidCost::TK008Sacrificed(v)=&mut f.already_paid[0]{v[1]=v[0].clone()},_=>f.source.card.definition=b::ID.into()};bad(&g,&x);}for id in [b::ID,b::TOKEN]{let mut d=b::definition(id);d.abilities[0].ops.clear();assert!(b::validate_definition(id,&d).is_err());assert!(b::validate_definition("JC125",&b::definition(id)).is_err());}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let command=serde_json::from_value(s["command"].clone()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap() as usize,Some(command),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"].as_str().unwrap());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn natural()->serde_json::Value{use crate::{deck,abi112_review_play_tests::Trace};fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="cq11-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("JC042",3),("JC125",44)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("cq11".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);(g.players[0].hand.iter().filter(|c|c.definition==b::ID).count()>=2&&g.players[0].hand.iter().any(|c|c.definition=="JC042")).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"cq11-natural-entry-sacrifice".into(),811);let mut done=false;let mut target=None;
for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let ids=if matches!(&p.resolution,ChoiceResolution::Declare{declaration,..}if declaration.source.card.definition==b::ID){p.choice.options.iter().take(1).map(|o|o.id.clone()).collect()}else{let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&c.definition==b::ID));opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(ids);continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let red=g.players[0].assets.iter().any(|c|catalog::card(&c.definition).color=="红");let a=if !red{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC042")))}else if g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else if g.cq11_trios(0).is_empty(){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::DESTROY))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(b::DESTROY){done=true;target=a.action.region;}t.action(0,a.action.clone());}else{t.pass();}}
assert!(done,"natural chain failed turn {}",t.room.game.turn);assert!(t.room.game.regions[target.unwrap()].destroyed);let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn cq11_native_natural_and_zero_reveal_export(){let mut g=game();let id=token(&mut g,0);g.hide_in_place(&id);let hidden=g.regions[0].cards[0].id.clone();let mut t=crate::abi112_review_play_tests::Trace::new_preserving_rng(g,"cq11-prepared-zero-reveal".into(),812);t.action(0,Action{card_id:Some(hidden),..Action::new("reveal")});for _ in 0..20{if t.room.game.stack.is_empty(){break;}t.pass();}assert!(!t.room.game.regions[0].cards[0].face_down);let cases=vec![natural(),duplicate(t.value())];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/cq11.rs",include_bytes!("cq11.rs").as_slice()),("rust-game/src/cq11_tests.rs",include_bytes!("cq11_tests.rs").as_slice()),("rust-game/src/generated.rs",include_bytes!("generated.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("CQ11_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn cq11_entry_original_region_survives_source_departure_but_not_replacement(){for replaced in [false,true]{let mut g=deploy();choose(&mut g,vec!["accept".into()]);let id=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();g.return_hand(&id);if replaced{g.regions[0].card=g.make_card("DQJC115",0);}restore(&mut g);top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition==b::TOKEN).count(),usize::from(!replaced));}}
#[test]fn cq11_region_replacement_after_sacrifice_does_not_destroy_new_instance(){let mut g=game();let t=token(&mut g,0);let a=token(&mut g,0);let c=token(&mut g,0);act(&mut g,0,activate(&t,vec![t.clone(),a,c]));g.regions[1].card=g.make_card("DQJC115",0);restore(&mut g);top(&mut g);assert!(!g.regions[1].destroyed);assert!(!g.batch3_physical_cards().any(|c|c.definition==b::TOKEN));}
#[test]fn cq11_generated_is_not_a_physical_deck_card_even_private_registry(){let mut d=crate::deck::preset("watchers").unwrap();d.society_id=None;d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:49},catalog::DeckEntry{card_id:b::TOKEN.into(),count:1}];let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::TOKEN).unwrap().supported=true;assert!(crate::deck::validate_with_cards(d,&cards).is_err());let mut g=game();let t=token(&mut g,0);let mut x=g.clone();x.board_mut(&t).unwrap().generated=None;bad(&g,&x);let c=x.regions[0].cards.remove(0);x.players[0].hand.push(c);bad(&g,&x);}
#[test]fn cq11_pending_trigger_cannot_change_accept_into_other_choice(){let g=deploy();for n in 0..3{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(1),1=>p.choice.options[0].id="other".into(),_=>if let ChoiceResolution::Declare{stage,..}=&mut p.resolution{*stage=DeclareChoice::Target}}bad(&g,&x);}}
